import{_ as r,a0 as a,w as s,s as p,I as n,x as i,a1 as o,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在Linux下使用Gitblit工具创建Git仓库服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux下使用Gitblit工具创建Git仓库服务 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux下使用Gitblit工具创建Git仓库服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux下使用Gitblit工具创建Git仓库服务 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux","title":"如何在Linux下使用Gitblit工具创建Git仓库服务","tag":"201506","desc":""},"relativePath":"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux.md","filePath":"[post].md"}'),g={name:"201506/20150330 How to Serve Git Repositories Using Gitblit Tool in Linux.md"};function u(b,t,m,h,x,G){const e=a("Link");return s(),p("div",null,[t[18]||(t[18]=n("h1",{id:"如何在linux下使用gitblit工具创建git仓库服务",tabindex:"-1"},[i("如何在Linux下使用Gitblit工具创建Git仓库服务 "),n("a",{class:"header-anchor",href:"#如何在linux下使用gitblit工具创建git仓库服务","aria-label":"Permalink to “如何在Linux下使用Gitblit工具创建Git仓库服务”"},"​")],-1)),n("p",null,[t[1]||(t[1]=i("嗨！朋友，今天我们将学习如何在你的Linux服务器或者PC上安装Gitblit工具。首先，我们看看什么是Git，它的功能以及安装Gitblit的步骤。",-1)),o(e,{href:"http://git-scm.com/"},{default:l(()=>[...t[0]||(t[0]=[i("Git是分布式版本控制系统",-1)])]),_:1}),t[2]||(t[2]=i("，它强调速度、数据一致性，并且支持分布式、非线性工作流。它最初由Linus Torvalds在2005年为Linux内核设计和开发，使用GPLv2证书，并从此成为软件开发中使用最广泛的版本控制系统。",-1))]),n("p",null,[o(e,{href:"http://gitblit.com/"},{default:l(()=>[...t[3]||(t[3]=[i("Gitblit是完全开源的软件",-1)])]),_:1}),t[4]||(t[4]=i("，它基于纯粹的Java堆栈，被设计以在Git仓库速度和效率方面胜任从小型到极大型的项目。它很容易学习和上手，并有着闪电般的性能。它在很多方面远胜 Subversion、CVS、Perforce和ClearCase等SCM（版本控制）工具，比如，如快速本地分支、易于暂存、多工作流等。",-1))]),t[19]||(t[19]=d(`<h4 id="gitblit的功能" tabindex="-1">Gitblit的功能 <a class="header-anchor" href="#gitblit的功能" aria-label="Permalink to “Gitblit的功能”">​</a></h4><ul><li>它可以做为一个哑仓库视图，没有管理控制以及用户账户。</li><li>它可以做为完整的Git服务，拥有克隆、推送和仓库访问控制。</li><li>它能独立于其他Git工具使用（包括实际的Git），它能和您已有的工具协作。</li></ul><h3 id="_1-创建gitblit安装目录" tabindex="-1">1.创建Gitblit安装目录 <a class="header-anchor" href="#_1-创建gitblit安装目录" aria-label="Permalink to “1.创建Gitblit安装目录”">​</a></h3><p>首先我们将在我们的服务器上建立一个目录，并在该目录下安装最新的Gitblit。</p><pre><code>$ sudo mkdir -p /opt/gitblit

$ cd /opt/gitblit
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/creating-directory-gitblit.png" alt="创建gitblit目录"></p><h3 id="_2-下载并解压" tabindex="-1">2. 下载并解压 <a class="header-anchor" href="#_2-下载并解压" aria-label="Permalink to “2. 下载并解压”">​</a></h3><p>现在，我们将从Gitblit官方站点下载最新版的Gitblit。这里我们将安装1.6.2版本。所以，请在安装时根据具体的版本对命令进行修改。</p><pre><code>$ sudo wget http://dl.bintray.com/gitblit/releases/gitblit-1.6.2.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/downloading-gitblit.png" alt="下载gitblit安装包"></p><p>接下来，我们将下载到的tar压缩包解压至之前创建的目录 /opt/gitblit/</p><pre><code>$ sudo tar -zxvf gitblit-1.6.2.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/extracting-gitblit-tar.png" alt="解压gitblit压缩包"></p><h3 id="_3-配置并运行" tabindex="-1">3.配置并运行 <a class="header-anchor" href="#_3-配置并运行" aria-label="Permalink to “3.配置并运行”">​</a></h3><p>现在，我们将对Gitblit进行配置。如果你想要定制Gitblit的行为，你可以修改<code>gitblit/data/gitblit.properties</code>。在完成配置后，我们将运行安装好的gitblit。有两种方式来运行gitblit，第一种是通过下面的命令手动运行：</p><pre><code>$ sudo java -jar gitblit.jar --baseFolder data
</code></pre><p>另一种是将gitblit添加为服务。下面是在linux下将gitblit添加为服务的步骤。</p><p>由于我在使用Ubuntu，下面的命令将是 sudo cp service-ubuntu.sh /etc/init.d/gitblit，所以请根据你的发行版修改文件名service-ubuntu.sh为相应的你运行的发行版。</p><pre><code>$ sudo ./install-service-ubuntu.sh

$ sudo service gitblit  start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/starting-gitblit-service.png" alt="启动gitblit服务"></p><p>在你的浏览器中打开<code>http://localhost:8080</code>或<code>https://localhost:8443</code>，也可以将localhost根据本地配置替换为IP地址。输入默认的管理员凭证：admin / admin并点击login按钮。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/gitblit-welcome.png" alt="gitblit欢迎页面"></p><p>现在，我们将添加一个新的用户。首先，你需要以admin用户登录，username = <strong>admin</strong>，password = <strong>admin</strong>。</p><p>然后，点击用户图标 &gt; users &gt; (+) new user 来创建一个新用户，如下图所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/add-user.png" alt="添加新用户"></p><p>现在，我们将创建一个开箱可用的仓库。点击 repositories &gt; (+) new repository。然后，如下图所示添加新的仓库。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/add-new-repository.png" alt="添加新的仓库"></p><h4 id="使用命令行创建一个新的仓库" tabindex="-1">使用命令行创建一个新的仓库 <a class="header-anchor" href="#使用命令行创建一个新的仓库" aria-label="Permalink to “使用命令行创建一个新的仓库”">​</a></h4><pre><code>    touch README.md
    git init
    git add README.md
    git commit -m &quot;first commit&quot;
    git remote add origin ssh://arunlinoxide@localhost:29418/linoxide.com.git
    git push -u origin master
</code></pre><p>请将其中的用户名arunlinoxide替换为你添加的用户名。</p><h4 id="在命令行中push一个已存在的仓库" tabindex="-1">在命令行中push一个已存在的仓库 <a class="header-anchor" href="#在命令行中push一个已存在的仓库" aria-label="Permalink to “在命令行中push一个已存在的仓库”">​</a></h4><pre><code>    git remote add origin ssh://arunlinoxide@localhost:29418/linoxide.com.git
    git push -u origin master
</code></pre><p><strong>注意</strong>：强烈建议所有人修改用户名“admin”的密码。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>欢呼吧！我们已经在Linux电脑中安装好了最新版本的Gitblit。接下来我们便可以在我们的大小项目中享受这样一个优美的版本控制系统。有了Gitblit，版本控制便再容易不过了。它有易于学习、轻量级、高性能的特点。因此，如果你有任何的问题、建议和反馈，请在留言处留言。</p><hr>`,36)),n("p",null,[t[6]||(t[6]=i("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/serve-git-repositories-gitblit/"},{default:l(()=>[...t[5]||(t[5]=[i("http://linoxide.com/linux-how-to/serve-git-repositories-gitblit/",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=i("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:l(()=>[...t[7]||(t[7]=[i("Arun Pyasi",-1)])]),_:1}),t[11]||(t[11]=i(" 译者：",-1)),o(e,{href:"https://github.com/wwy-hust"},{default:l(()=>[...t[8]||(t[8]=[i("wwy-hust",-1)])]),_:1}),t[12]||(t[12]=i(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[9]||(t[9]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=i("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[i("LCTT",-1)])]),_:1}),t[16]||(t[16]=i(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[i("Linux中国",-1)])]),_:1}),t[17]||(t[17]=i(" 荣誉推出",-1))])])}const T=r(g,[["render",u]]);export{w as __pageData,T as default};
